{
  "segment_function": "conclusion",
  "claims": [
    {
      "claim": "The modern economy has increasingly become a waste economy characterized by the rapid consumption and discarding of goods to keep economic processes going.",
      "claim_type": "author_position",
      "supporting_excerpt": "One of the obvious danger signs that we may be on our way to bring into existence the ideal of the animal laborans is the extent to which our whole economy has become a waste economy, in which things must be almost as quickly devoured and discarded as they have appeared in the world, if the process itself is not to come to a sudden catastrophic end.",
      "support_kind": "direct",
      "confidence": 1
    },
    {
      "claim": "The human world consists of things that are used rather than consumed, and these durable things provide the condition that enables human life to be at home on earth.",
      "claim_type": "author_position",
      "supporting_excerpt": "The world, the man-made home erected on earth and made of the material which earthly nature delivers into human hands, consists not of things that are consumed but of things that are used. If nature and the earth generally constitute the condition of human life , then the world and the things of the world constitute the condition under which this specifically human life can be at home on earth.",
      "support_kind": "direct",
      "confidence": 1
    }
  ],
  "definitions": [
    {
      "term": "the world",
      "definition": "The man-made home erected on earth, consisting of things that are used rather than consumed, whose permanence stands in contrast to biological life."
    }
  ],
  "distinctions": [
    {
      "item_a": "nature",
      "item_b": "the world",
      "distinction": "Nature constitutes the general condition of human life and provides materials, whereas the world and its things constitute the condition under which specifically human life can be at home on earth through durability and use."
    }
  ]
}

